program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)
    out = [row[:] for row in grid]
    if not color:
        return out
    points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    comp = {}
    cid = 0
    for point in points:
        if point in comp:
            continue
        stack = [point]
        comp[point] = cid
        while stack:
            r, c = stack.pop()
            for nr in (r - 1, r + 1):
                for nc in (c - 1, c + 1):
                    q = (nr, nc)
                    if q in points and q not in comp:
                        comp[q] = cid
                        stack.append(q)
        cid += 1
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == color]
        for i, left in enumerate(cols):
            for right in cols[i + 1:]:
                if comp[(r, left)] == comp[(r, right)]:
                    for c in range(left + 1, right):
                        if out[r][c] == 0:
                            out[r][c] = 2
    return out
'''
p.parent.mkdir(parents=True, exist_ok=True)
p.write_text(program)
